"""Corrections to the Tukan CSV, obtained by rebuilding the monthly averages from Banxico's official weekly
auctions (SIE, table CF107, retrieved 12-Oct-2026).
Series: CETES 28/91/182/364 = SF43936/SF43939/SF43942/SF43945; Bonos M 3/5/10/20/30 = SF43883/SF43886/SF44071/SF45384/SF60696.
Comparison result (1,936 values): 1,799 identical, 117 differ only by rounding (<=0.02 pp), 20 differ by more;
2 observations exist in Banxico and are missing in Tukan.

Usage: imported by yield_curve.py when DATA=corrected (the default): `raw = banxico_corrections.correct(raw)`.
"""
# 1) 364-day CETE: Tukan is systematically HIGHER (never lower) in 125 months; official Banxico value:
CETE364 = dict(x.split(':') for x in """200610:7.480 200612:7.250 200702:7.360 200704:7.360 200706:7.560 200708:7.615 200709:7.680 200711:7.860 200801:7.800 200803:7.480 200805:7.830 200807:8.635 200808:8.690 200810:8.340 200812:8.050 200902:7.140 200904:6.120 200906:5.190 200909:5.350 200911:5.220 201001:4.980 201003:5.070 201005:4.950 201007:4.790 201008:4.770 201010:4.650 201012:4.850 201102:4.810 201104:4.920 201107:4.640 201109:4.450 201111:4.460 201201:4.700 201203:4.630 201205:4.595 201206:4.600 201208:4.580 201210:4.630 201212:4.610 201302:4.310 201304:4.100 201307:4.000 201309:3.700 201401:3.650 201403:3.670 201505:3.500 201507:3.620 201509:3.710 201511:3.690 201604:4.030 201606:4.460 201608:4.750 201610:5.220 201612:6.200 201702:6.920 201703:6.910 201705:7.230 201707:7.230 201709:7.180 201711:7.270 201801:7.780 201803:7.825 201804:7.710 201806:8.100 201808:8.150 201810:8.200 201812:8.670 201901:8.520 201903:8.050 201905:8.280 201907:8.040 201909:7.390 201911:7.120 202002:6.660 202004:5.790 202006:4.900 202101:4.212 202103:4.410 202110:6.223 202201:6.982 202202:7.163 202203:8.038 202204:8.555 202205:8.838 202206:9.446 202207:9.712 202208:9.598 202209:10.274 202210:10.760 202211:10.825 202212:10.853 202301:11.080 202302:11.650 202303:11.865 202304:11.755 202305:11.535 202306:11.293 202307:11.350 202308:11.465 202309:11.615 202310:11.740 202311:11.503 202312:11.175 202401:11.200 202402:11.230 202403:11.120 202404:11.205 202405:11.393 202406:11.375 202407:11.390 202408:10.915 202409:10.540 202410:10.337 202411:10.345 202412:9.960 202503:9.050 202505:8.350 202506:8.290 202507:8.280 202510:7.503 202511:7.570 202512:7.600 202601:7.470 202604:7.263 202609:7.120""".split())
# 2) March 2021: the 31-Mar-2021 auction (Wednesday of Holy Week) is missing for all instruments.
#    Official weekly results of that auction: 28d 4.08, 91d 4.16, 182d 4.33, 364d 4.70, 3-year Bono 4.90.
MAR2021 = {"3m": 4.074, "6m": 4.194, "12m": 4.410, "3y": 4.545}   # official monthly averages (28d matches: 4.05)
# 3) July 2010: Banxico reports auctions that Tukan omits: 20-year Bono 7.31 (15-Jul) and 30-year Bono 7.38 (29-Jul).
JUL2010 = {"20y": 7.31, "30y": 7.38}

def correct(raw):
    """Return a copy of the monthly rate panel `raw` (columns 1m..30y) with the Banxico corrections applied."""
    import pandas as pd
    r = raw.copy()
    for k, v in CETE364.items():
        r.loc[pd.Timestamp(k[:4] + "-" + k[4:] + "-01"), "12m"] = float(v)
    for c, v in MAR2021.items(): r.loc[pd.Timestamp("2021-03-01"), c] = v
    for c, v in JUL2010.items(): r.loc[pd.Timestamp("2010-07-01"), c] = v
    return r
